    .carousel-slide:nth-child(2) { background: linear-gradient(135deg, #0d0d1a, #1a001a); }
    .carousel-slide:nth-child(3) { background: linear-gradient(135deg, #001a0d, #001a1a); }
    .carousel-slide:nth-child(4) { background: linear-gradient(135deg, #1a1a00, #1a0d00); }
