/* ── RedRoom Fitness — Shared Design System ── */

:root {
  --red: #FF0000;
  --red-dark: #cc0000;
  --bg: #141414;
  --bg-deep: #0a0a0a;
  --bg-card: #0d0d0d;
  --text: #ffffff;
  --text-muted: rgba(255,255,255,0.55);
  --text-dim: rgba(255,255,255,0.3);
  --border: rgba(255,255,255,0.07);
  --border-red: rgba(255,0,0,0.2);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; }
a { text-decoration: none; color: inherit; }
button { cursor: pointer; border: none; background: none; }

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: 'Oswald', sans-serif;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 14px 36px;
  font-size: 14px;
  transition: all 0.2s ease;
  position: relative;
  overflow: hidden;
}

.btn-primary {
  background: var(--red);
  color: #fff;
}
.btn-primary:hover {
  background: var(--red-dark);
  transform: translateY(-1px);
  box-shadow: 0 8px 24px rgba(255,0,0,0.35);
}

.btn-outline {
  background: transparent;
  color: #fff;
  border: 1px solid rgba(255,255,255,0.3);
}
.btn-outline:hover {
  border-color: var(--red);
  color: var(--red);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: rgba(255,255,255,0.7);
  border: 1px solid rgba(255,255,255,0.1);
}
.btn-ghost:hover {
  background: rgba(255,255,255,0.05);
  color: #fff;
}

.btn-dark {
  background: #000;
  color: #fff;
  border: 2px solid #000;
}
.btn-dark:hover {
  background: #111;
  transform: translateY(-2px);
  box-shadow: 0 12px 32px rgba(0,0,0,0.5);
}

.btn-lg { padding: 18px 52px; font-size: 15px; }
.btn-sm { padding: 10px 22px; font-size: 12px; }

/* ── Navigation ── */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: rgba(10,10,10,0.95);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
  transition: background 0.3s;
}

.nav.has-topbar { top: 0; }

.nav-inner {
  display: flex;
  align-items: center;
  gap: 40px;
  padding: 0 48px;
  height: 68px;
  max-width: 1600px;
  margin: 0 auto;
}

.nav-logo {
  font-family: 'Oswald', sans-serif;
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #fff;
  flex-shrink: 0;
}
.nav-logo span { color: var(--red); }

.nav-links {
  display: flex;
  list-style: none;
  gap: 32px;
  flex: 1;
}
.nav-links a {
  font-family: 'Inter', sans-serif;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.6);
  transition: color 0.2s;
}
.nav-links a:hover, .nav-links a.active { color: #fff; }

.nav-ctas {
  display: flex;
  gap: 12px;
  flex-shrink: 0;
}

.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  margin-left: auto;
}
.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: #fff;
  transition: all 0.3s;
}

/* Page offset for fixed nav */
.page-offset {
  padding-top: 104px; /* nav (68px) + topbar (~36px) */
}

/* ── Newsletter Section ── */
.newsletter-section {
  background: #0d0d0d;
  padding: 100px 48px;
  border-top: 1px solid var(--border);
}
.newsletter-inner {
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
}
.newsletter-title {
  font-family: 'Oswald', sans-serif;
  font-size: clamp(32px, 4vw, 52px);
  font-weight: 700;
  text-transform: uppercase;
  color: #fff;
  line-height: 1;
  margin-bottom: 16px;
}
.newsletter-body {
  font-family: 'Inter', sans-serif;
  font-size: 15px;
  line-height: 1.7;
  color: var(--text-muted);
  margin-bottom: 36px;
}
.newsletter-input-group {
  display: flex;
  gap: 0;
}
.newsletter-input {
  flex: 1;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-right: none;
  color: #fff;
  font-family: 'Inter', sans-serif;
  font-size: 14px;
  padding: 14px 20px;
  outline: none;
  transition: border-color 0.2s;
}
.newsletter-input::placeholder { color: rgba(255,255,255,0.3); }
.newsletter-input:focus { border-color: rgba(255,0,0,0.4); }
.newsletter-input.error { border-color: rgba(255,100,100,0.6); }
.newsletter-msg {
  margin-top: 12px;
  font-family: 'Inter', sans-serif;
  font-size: 13px;
  min-height: 20px;
}
.newsletter-msg.success { color: #4ade80; }
.newsletter-msg.error { color: #f87171; }

/* ── Footer ── */
.site-footer {
  background: #0a0a0a;
  border-top: 1px solid var(--border);
  padding: 80px 48px 0;
}
.footer-inner {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 60px;
  max-width: 1400px;
  margin: 0 auto;
  padding-bottom: 64px;
  border-bottom: 1px solid var(--border);
}
.footer-tagline {
  font-family: 'Inter', sans-serif;
  font-size: 13px;
  color: var(--text-muted);
  margin-bottom: 24px;
}
.footer-col-title {
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.35);
  margin-bottom: 20px;
}
.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.footer-links a {
  font-family: 'Inter', sans-serif;
  font-size: 14px;
  color: var(--text-muted);
  transition: color 0.2s;
}
.footer-links a:hover { color: var(--red); }
.footer-bottom {
  max-width: 1400px;
  margin: 0 auto;
  padding: 24px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.footer-bottom p {
  font-family: 'Inter', sans-serif;
  font-size: 13px;
  color: var(--text-dim);
}
.footer-legal {
  display: flex;
  gap: 24px;
}
.footer-legal a {
  font-family: 'Inter', sans-serif;
  font-size: 13px;
  color: var(--text-dim);
  transition: color 0.2s;
}
.footer-legal a:hover { color: rgba(255,255,255,0.5); }

.country-select {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  color: rgba(255,255,255,0.6);
  font-family: 'Inter', sans-serif;
  font-size: 13px;
  padding: 8px 12px;
  outline: none;
  cursor: pointer;
  transition: border-color 0.2s;
}
.country-select:hover { border-color: rgba(255,0,0,0.3); }
.country-select option { background: #1a1a1a; }

/* ── Page Hero (inner pages) ── */
.page-hero {
  background: #141414;
  padding: 160px 48px 100px;
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 80% at 80% 50%, rgba(255,0,0,0.12) 0%, transparent 65%);
}
.page-hero-inner {
  position: relative;
  z-index: 1;
  max-width: 1400px;
  margin: 0 auto;
}
.page-hero-eyebrow {
  font-family: 'Inter', sans-serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 20px;
}
.page-hero-title {
  font-family: 'Oswald', sans-serif;
  font-size: clamp(48px, 7vw, 100px);
  font-weight: 700;
  text-transform: uppercase;
  color: #fff;
  line-height: 0.92;
  margin-bottom: 24px;
}
.page-hero-subtitle {
  font-family: 'Inter', sans-serif;
  font-size: 17px;
  line-height: 1.7;
  color: var(--text-muted);
  max-width: 540px;
}

/* ── Utilities ── */
.section-label {
  font-family: 'Inter', sans-serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 16px;
}
.section-title {
  font-family: 'Oswald', sans-serif;
  font-size: clamp(36px, 4.5vw, 64px);
  font-weight: 700;
  text-transform: uppercase;
  color: #fff;
  line-height: 0.95;
  margin-bottom: 60px;
}

/* Red rule divider */
.red-rule {
  width: 48px;
  height: 3px;
  background: var(--red);
  margin-bottom: 24px;
}

/* ── Responsive ── */
@media (max-width: 1024px) {
  .footer-inner { grid-template-columns: 1fr 1fr; gap: 40px; }
}

@media (max-width: 768px) {
  .nav-links { display: none; flex-direction: column; position: absolute; top: 100%; left: 0; right: 0; background: rgba(10,10,10,0.98); padding: 24px 48px; gap: 16px; border-bottom: 1px solid var(--border); }
  .nav-links.open { display: flex; }
  .nav-ctas { display: none; }
  .nav-toggle { display: flex; }
  .nav-inner { flex-wrap: wrap; }

  .page-hero { padding: 120px 24px 80px; }
  .newsletter-section { padding: 80px 24px; }
  .site-footer { padding: 60px 24px 0; }
  .footer-inner { grid-template-columns: 1fr; gap: 32px; padding-bottom: 40px; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
  .footer-legal { flex-wrap: wrap; justify-content: center; }
}

@media (max-width: 480px) {
  .newsletter-input-group { flex-direction: column; }
  .newsletter-input { border-right: 1px solid rgba(255,255,255,0.1); border-bottom: none; }
}

